def preservar_datos_anteriores(apps, schema_editor):
    """Asigna catálogos por uso histórico sin exponer registros entre empresas."""
    Empresa = apps.get_model('facturacion', 'Empresa')
    Cliente = apps.get_model('facturacion', 'Cliente')
    Producto = apps.get_model('facturacion', 'Producto')
    Comprobante = apps.get_model('facturacion', 'Comprobante')
    Detalle = apps.get_model('facturacion', 'DetalleComprobante')
    unica = Empresa.objects.first() if Empresa.objects.count() == 1 else None
    for modelo in [Cliente, Producto]:
        for registro in modelo.objects.all().iterator():
            if modelo == Cliente:
                usos = Comprobante.objects.filter(cliente=registro).exclude(empresa=None)
            else:
                usos = Comprobante.objects.filter(detalles__producto=registro).exclude(empresa=None)
            empresas = list(usos.values_list('empresa_id', flat=True).distinct())
            if not empresas and unica:
                empresas = [unica.pk]
            for indice, empresa_id in enumerate(empresas):
                valores = {campo.name: getattr(registro, campo.name) for campo in modelo._meta.fields if campo.name not in {'id', 'empresa'}}
                if indice == 0:
                    registro.empresa_id = empresa_id
                    registro.save(update_fields=['empresa'])
                    continue
                copia = modelo.objects.create(empresa_id=empresa_id, **valores)
                if modelo == Cliente:
                    Comprobante.objects.filter(empresa_id=empresa_id, cliente=registro).update(cliente=copia)
                else:
                    Detalle.objects.filter(comprobante__empresa_id=empresa_id, producto=registro).update(producto=copia)
    for documento in Comprobante.objects.select_related('empresa', 'cliente').all().iterator():
        if not documento.empresa_id and unica:
            documento.empresa = unica
        empresa = documento.empresa
        cliente = documento.cliente
        documento.datos_historicos = {
            'empresa': {'ruc': empresa.ruc, 'razon_social': empresa.razon_social, 'direccion': empresa.direccion} if empresa else {},
            'cliente': {'num_doc': cliente.num_doc, 'tipo_doc': cliente.tipo_doc, 'razon_social': cliente.razon_social, 'direccion': cliente.direccion},
        }
        # Un número preexistente es evidencia histórica: se conserva, nunca se recicla.
        if documento.estado == 'BORRADOR' and documento.numero:
            documento.estado = 'EMITIDO'
        documento.save()
    for detalle in Detalle.objects.select_related('producto').all().iterator():
        detalle.descripcion_historica = detalle.producto.descripcion
        detalle.unidad_historica = detalle.producto.unidad_medida
        detalle.afecto_igv_historico = detalle.producto.afecto_igv
        detalle.save()


